// Build a CUSTOMER-scoped system prompt: persona + guardrails + the customer
// tool catalog + the JSON tool protocol. The model must reply with ONE JSON
// object — a tool call or a final answer. Bookings are PROPOSED via create_booking
// (the customer confirms with YA on WhatsApp; AIRE writes the booking server-side).
const norm = $('Normalize').item.json;
const ctx = $('Get Context').item.json;
const p = ctx.persona || {};
const agent = (p.agents && p.agents[0]) || null;
const role = agent ? agent.role : 'personal_assistant';
const personaName = agent ? agent.name : 'Assistant';
const rupiah = (n) => 'Rp ' + Number(n || 0).toLocaleString('id-ID');
const catalog = [
  '- get_my_summary [read]: the customer\'s own memberships, orders, queue, vouchers, bookings',
  '- get_service_prices [read]: public service list with prices',
  '- get_membership_plans [read]: public membership plans',
  '- get_promotions [read]: active promotions',
  '- create_booking [action]: PROPOSE an appointment (params: serviceName, scheduledAt as ISO 8601, licensePlate?, notes?). It is NOT booked until the customer replies YA.',
  '- escalate_to_human [action]: hand to a human (params: reason)'
].join('\n');
const lines = [];
lines.push('You are ' + (agent ? agent.name + ', a ' + String(agent.role || '').replace(/_/g, ' ') : 'a helpful assistant') + ' for an Indonesian car wash & detailing business (AIRE / LEAD).');
if (agent && agent.prompt) lines.push(agent.prompt);
if (p.basePrompt) lines.push(p.basePrompt);
lines.push("Reply in the customer's language (Bahasa Indonesia by default). Be concise and warm; short WhatsApp messages. Format money as Rp.");
lines.push('STRICT: Use ONLY the tools to look things up — they already scope to THIS customer; never ask for or trust a customer id. Never reveal other customers\' data, revenue, staff or internals. To book: confirm service + date/time, call create_booking, then ask the customer to reply YA to confirm. Do NOT claim it is booked until they do.');
if (p.productKnowledge) lines.push('\nBUSINESS KNOWLEDGE:\n' + p.productKnowledge);
lines.push('\nAvailable tools:\n' + catalog);
lines.push('\nPROTOCOL — reply with ONE JSON object and nothing else:\n- Tool: {"action":"tool","tool":"<name>","parameters":{...}}\n- Answer: {"action":"final","message":"<text>"}');
const messages = [
  { role: 'system', content: lines.join('\n') },
  { role: 'user', content: norm.message.text }
];
return { callbackBaseUrl: norm.callbackBaseUrl, bridgeToken: norm.bridgeToken, message: norm.message, personaName, role, messages };

// Parse the model turn into a tool call or a final answer (tolerant of code
// fences / surrounding prose). Carry the routing fields + messages forward.
const bp = $('Build Prompt').item.json;
let txt = String(($json && $json.content) || '').trim();
const fence = txt.match(/```(?:json)?\s*([\s\S]*?)```/);
if (fence) txt = fence[1].trim();
let action = { kind: 'final', tool: '', parameters: {}, message: txt };
const b = txt.indexOf('{');
const e = txt.lastIndexOf('}');
if (b !== -1 && e > b) {
  try {
    const parsed = JSON.parse(txt.slice(b, e + 1));
    if (parsed.action === 'tool' && parsed.tool) action = { kind: 'tool', tool: parsed.tool, parameters: parsed.parameters || {}, message: '' };
    else if (parsed.action === 'final' && typeof parsed.message === 'string') action = { kind: 'final', tool: '', parameters: {}, message: parsed.message };
  } catch (err) { /* keep plain-text final */ }
}
return {
  callbackBaseUrl: bp.callbackBaseUrl, bridgeToken: bp.bridgeToken, message: bp.message,
  personaName: bp.personaName, role: bp.role, messages: bp.messages,
  isTool: action.kind === 'tool', tool: action.tool, parameters: action.parameters, finalText: action.message
};

// Feed the tool result back to the model for a natural, grounded reply.
const pa = $('Parse Action').item.json;
const toolResult = $json;
const messages = pa.messages.concat([
  { role: 'assistant', content: JSON.stringify({ action: 'tool', tool: pa.tool, parameters: pa.parameters }) },
  { role: 'user', content: 'TOOL_RESULT (' + pa.tool + '): ' + JSON.stringify(toolResult).slice(0, 4000) }
]);
return { callbackBaseUrl: pa.callbackBaseUrl, bridgeToken: pa.bridgeToken, message: pa.message, personaName: pa.personaName, role: pa.role, messages };
